{"command":"cat <<'RS' > src/main.rs
use clap::{Arg, Command};
use ratatui::{
    layout::{Alignment, Constraint, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, BorderType, Paragraph},
    Frame,
};
use crossterm::event::{self, Event, KeyCode};

fn cli() -> Command {
    Command::new("parqeye")
        .version("0.0.2")
        .about("Command line tool to visualize parquet files")
        .arg(Arg::new("PATH").help("Path to the parquet file").required(true))
}

struct App {
    path: String,
    tab: usize, // 0 Visualize, 1 Metadata, 2 Schema, 3 RowGroups
    // Visualize state
    headers: Vec<String>,
    rows: Vec<Vec<String>>,
    col_widths: Vec<usize>, // includes +2 padding, min 10 max 27
    selected_row: usize,
    row_offset: usize,
    col_offset: usize, // index of first visible col
}

impl App {
    fn new(path: String) -> Self {
        // Fake data for alltypes_plain for dev
        let headers = vec!["id","bool_col","tinyint_col","smallint_col","int_col","bigint_col","float_col","double_col","date_string_col","string_col","timestamp_col"].into_iter().map(|s| s.to_string()).collect::<Vec<_>>();
        let rows = vec![
            vec!["4","true","0","0","0","0","0.0","0.0","b\"03/01/09\"","b\"0\"","2009-03-01 00:00:00"],
            vec!["5","false","1","1","1","10","1.1","10.1","b\"03/01/09\"","b\"1\"","2009-03-01 00:01:00"],
            vec!["6","true","0","0","0","0","0.0","0.0","b\"04/01/09\"","b\"0\"","2009-04-01 00:00:00"],
            vec!["7","false","1","1","1","10","1.1","10.1","b\"04/01/09\"","b\"1\"","2009-04-01 00:01:00"],
            vec!["2","true","0","0","0","0","0.0","0.0","b\"02/01/09\"","b\"0\"","2009-02-01 00:00:00"],
            vec!["3","false","1","1","1","10","1.1","10.1","b\"02/01/09\"","b\"1\"","2009-02-01 00:01:00"],
            vec!["0","true","0","0","0","0","0.0","0.0","b\"01/01/09\"","b\"0\"","2009-01-01 00:00:00"],
            vec!["1","false","1","1","1","10","1.1","10.1","b\"01/01/09\"","b\"1\"","2009-01-01 00:01:00"],
        ].into_iter().map(|r| r.into_iter().map(|s| s.to_string()).collect()).collect::<Vec<Vec<String>>>();
        let mut col_widths = Vec::new();
        for (ci, h) in headers.iter().enumerate() {
            let mut max_len = h.len();
            for row in &rows {
                let l = row[ci].len();
                if l > max_len { max_len = l; }
            }
            let capped = std::cmp::min(max_len, 25);
            let w = capped + 2;
            let w = std::cmp::max(w, 10);
            col_widths.push(w);
        }
        Self { path, tab: 0, headers, rows, col_widths, selected_row: 0, row_offset: 0, col_offset: 0 }
    }

    fn visible_height(&self, body_height: u16) -> usize {
        // body includes header row (1) + separator (1) + data rows
        if body_height <= 2 { 0 } else { (body_height - 2) as usize }
    }

    fn truncate_cell(s: &str) -> String {
        if s.len() <= 25 {
            s.to_string()
        } else {
            // truncate to 24 chars + ellipsis (handle unicode? for now bytes, but need char boundary)
            // Count chars
            let chars: Vec<char> = s.chars().collect();
            if chars.len() <= 25 {
                s.to_string()
            } else {
                chars[..24].iter().collect::<String>() + "…"
            }
        }
    }
}

fn main() -> std::io::Result<()> {
    let matches = cli().get_matches();
    let path = matches.get_one::<String>("PATH").unwrap().clone();
    let mut terminal = ratatui::init();
    let mut app = App::new(path);
    loop {
        terminal.draw(|f| draw(f, &mut app)).map_err(|e| std::io::Error::other(e.to_string()))?;
        match event::read().map_err(|e| std::io::Error::other(e.to_string()))? {
            Event::Key(key) => {
                match key.code {
                    KeyCode::Char(c) => {
                        let lc = c.to_ascii_lowercase();
                        if lc == 'q' {
                            break;
                        } else if lc == 'u' {
                            // page up
                            handle_page_up(&mut app, terminal.get_frame().area());
                        } else if lc == 'd' {
                            handle_page_down(&mut app, terminal.get_frame().area());
                        }
                    }
                    KeyCode::Tab => {
                        app.tab = (app.tab + 1) % 4;
                    }
                    KeyCode::BackTab => {
                        app.tab = (app.tab + 3) % 4;
                    }
                    KeyCode::Up => {
                        if app.tab == 0 {
                            if app.selected_row > 0 {
                                app.selected_row -= 1;
                                if app.selected_row < app.row_offset {
                                    app.row_offset = app.selected_row;
                                }
                            }
                        }
                    }
                    KeyCode::Down => {
                        if app.tab == 0 {
                            if !app.rows.is_empty() && app.selected_row + 1 < app.rows.len() {
                                app.selected_row += 1;
                                // need visible height to decide scroll; get from terminal size?
                                // For now, use last known? We'll compute from terminal area
                                let area = terminal.get_frame().area();
                                let body_h = area.height.saturating_sub(4); // header 3 + footer 1
                                let vis = if body_h <= 2 { 0 } else { (body_h - 2) as usize };
                                if vis > 0 && app.selected_row >= app.row_offset + vis - 1 {
                                    // scroll to keep second-last? original: offset = sel - vis + 2
                                    app.row_offset = app.selected_row.saturating_sub(vis.saturating_sub(2));
                                }
                            }
                        }
                    }
                    KeyCode::Left => {
                        if app.tab == 0 {
                            if app.col_offset > 0 {
                                app.col_offset -= 1;
                            }
                        }
                    }
                    KeyCode::Right => {
                        if app.tab == 0 {
                            // need to check if can scroll right (more cols hidden)
                            // For now, allow up to headers.len()-1
                            if app.col_offset + 1 < app.headers.len() {
                                app.col_offset += 1;
                            }
                        }
                    }
                    _ => {}
                }
            }
            Event::Resize(_, _) => {}
            _ => {}
        }
    }
    ratatui::restore();
    Ok(())
}

fn handle_page_up(app: &mut App, area: Rect) {
    if app.tab != 0 || app.rows.is_empty() { return; }
    let body_h = area.height.saturating_sub(4);
    let vis = if body_h <= 2 { 0 } else { (body_h - 2) as usize };
    if vis == 0 { return; }
    let page = vis.saturating_sub(1);
    if page == 0 { return; }
    app.selected_row = app.selected_row.saturating_sub(page);
    if app.selected_row < app.row_offset {
        app.row_offset = app.selected_row;
    }
}

fn handle_page_down(app: &mut App, area: Rect) {
    if app.tab != 0 || app.rows.is_empty() { return; }
    let body_h = area.height.saturating_sub(4);
    let vis = if body_h <= 2 { 0 } else { (body_h - 2) as usize };
    if vis == 0 { return; }
    let page = vis.saturating_sub(1);
    if page == 0 { return; }
    let max_idx = app.rows.len() - 1;
    app.selected_row = std::cmp::min(app.selected_row + page, max_idx);
    if app.selected_row >= app.row_offset + vis.saturating_sub(1) {
        // second-last logic: offset = sel - vis + 2
        if vis >= 2 {
            app.row_offset = app.selected_row.saturating_sub(vis - 2);
        } else {
            app.row_offset = app.selected_row;
        }
        // clamp offset to max
        let max_offset = app.rows.len().saturating_sub(vis);
        if app.row_offset > max_offset {
            app.row_offset = max_offset;
        }
    }
}

fn draw(f: &mut Frame, app: &mut App) {
    let area = f.area();
    let chunks = Layout::vertical([Constraint::Length(3), Constraint::Min(0), Constraint::Length(1)]).split(area);
    draw_header(f, chunks[0], app);
    match app.tab {
        0 => draw_visualize(f, chunks[1], app),
        1 => draw_metadata(f, chunks[1], app),
        2 => draw_schema(f, chunks[1], app),
        3 => draw_rowgroups(f, chunks[1], app),
        _ => {}
    }
    draw_footer(f, chunks[2], app);
}

fn draw_header(f: &mut Frame, area: Rect, app: &App) {
    let block = Block::default().borders(Borders::ALL).border_type(BorderType::Rounded).border_style(Style::default().fg(Color::Indexed(11)));
    let inner = block.inner(area);
    f.render_widget(block, area);
    // Tabs
    let tabs = ["Visualize", "Metadata", "Schema", "Row Groups"];
    let mut spans = Vec::new();
    for (i, t) in tabs.iter().enumerate() {
        if i > 0 { spans.push(Span::raw("   ")); }
        if i == app.tab {
            spans.push(Span::styled(*t, Style::default().add_modifier(Modifier::REVERSED)));
        } else {
            spans.push(Span::raw(*t));
        }
    }
    let tabs_line = Line::from(spans);
    // Render tabs at inner.x+1, inner.y (1 space padding)
    // Need to handle width: tabs take left, filename right
    // Compute tabs width: sum len + separators
    let tabs_width: usize = tabs.iter().map(|s| s.len()).sum::<usize>() + 3*3; // 3 separators *3 spaces
    let tabs_area = Rect { x: inner.x + 1, y: inner.y, width: tabs_width as u16, height: 1 };
    f.render_widget(Paragraph::new(tabs_line), tabs_area);
    // Filename right-aligned with 1 space padding from border
    let fname = app.path.clone();
    let fw = fname.len() as u16;
    // inner.width includes full inner (excluding borders). Right pad 1.
    if (fw + 1) <= inner.width {
        let fx = inner.x + inner.width - 1 - fw;
        let farea = Rect { x: fx, y: inner.y, width: fw, height: 1 };
        let span = Span::styled(fname, Style::default().fg(Color::Indexed(2)));
        f.render_widget(Paragraph::new(Line::from(span)), farea);
    }
}

fn draw_footer(f: &mut Frame, area: Rect, app: &App) {
    // Left: parqeye bold green
    // Right: hints per tab, right-aligned
    let left = Span::styled("parqeye", Style::default().fg(Color::Indexed(2)).add_modifier(Modifier::BOLD));
    // Build right hints
    let right_line: Line = match app.tab {
        0 => Line::from(vec![
            Span::styled("↑", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("↓", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Row"),
            Span::styled(" | ", Style::default().fg(Color::Indexed(15))),
            Span::styled("→", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("←", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Column"),
            Span::styled(" | ", Style::default().fg(Color::Indexed(15))),
            Span::styled("u", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("d", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Page - "),
            Span::styled("[Tab]", Style::default().fg(Color::Indexed(2))),
            Span::raw(" Next Tab, "),
            Span::styled("[Q]", Style::default().fg(Color::Indexed(4))),
            Span::raw("uit"),
        ]),
        1 => Line::from(vec![
            Span::styled("[Tab]", Style::default().fg(Color::Indexed(2))),
            Span::raw(" Next Tab, "),
            Span::styled("[Q]", Style::default().fg(Color::Indexed(4))),
            Span::raw("uit"),
        ]),
        2 => Line::from(vec![
            Span::styled("←", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("→", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Scroll, "),
            Span::styled("↑", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("↓", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Schema - "),
            Span::styled("[Tab]", Style::default().fg(Color::Indexed(2))),
            Span::raw(" Next Tab, "),
            Span::styled("[Q]", Style::default().fg(Color::Indexed(4))),
            Span::raw("uit"),
        ]),
        3 => Line::from(vec![
            Span::styled("→", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("←", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Iterate Row Groups, "),
            Span::styled("↑", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("↓", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Schema - "),
            Span::styled("[Tab]", Style::default().fg(Color::Indexed(2))),
            Span::raw(" Next Tab, "),
            Span::styled("[Q]", Style::default().fg(Color::Indexed(4))),
            Span::raw("uit"),
        ]),
        _ => Line::from(""),
    };
    // Render left at x, right right-aligned
    f.render_widget(Paragraph::new(Line::from(left)), Rect { x: area.x, y: area.y, width: 7, height: 1 });
    let rw = right_line.width() as u16;
    if rw <= area.width.saturating_sub(8) {
        let rx = area.x + area.width - rw;
        f.render_widget(Paragraph::new(right_line), Rect { x: rx, y: area.y, width: rw, height: 1 });
    } else {
        // not enough space, just render truncated? For small terminals, hints may be cut. Original behavior for small width? Need to handle.
        // For now, render right-aligned with available width (may truncate left part?)
        // Actually original at small width still shows hints? Let's just render with available width, ratatui will truncate?
        let rx = area.x + 8;
        let w = area.width.saturating_sub(8);
        f.render_widget(Paragraph::new(right_line), Rect { x: rx, y: area.y, width: w, height: 1 });
    }
}

fn draw_visualize(f: &mut Frame, area: Rect, app: &App) {
    if area.height == 0 || area.width == 0 { return; }
    // area is body (without header/footer)
    // Need to render: col headers row (y=0), separator (y=1), data rows (y=2..)
    // Row number area width 6, separator │ at x=6, data starts at x=9 (6+1+2)
    // Header line: 9 spaces + headers
    // Separator: ──────┬────... in grey
    // Data: row_num (grey or bold+underline+grey) + │ + cells
    let header_style = Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD);
    let grey = Style::default().fg(Color::Indexed(8));
    let sel_row_num_style = Style::default().fg(Color::Indexed(8)).add_modifier(Modifier::BOLD | Modifier::UNDERLINED);
    let sel_cell_style = Style::default().fg(Color::Indexed(15)).bg(Color::Rgb(60,60,60)).add_modifier(Modifier::BOLD);

    // Determine visible cols based on col_offset and area.width
    // Data starts at x=9 (0-indexed within area? area.x is 0, data at area.x+9)
    // Available width for data = area.width.saturating_sub(9)
    let avail = area.width.saturating_sub(9) as usize;
    let mut visible_cols: Vec<usize> = Vec::new();
    let mut used = 0usize;
    for ci in app.col_offset..app.headers.len() {
        let w = app.col_widths[ci];
        if used + w <= avail || visible_cols.is_empty() {
            // Always show at least one col even if wider than avail? Original shows truncated last col at edge (cut, not ellipsis? For Visualize, last col truncated at screen edge without ellipsis? Actually for Visualize, cells truncated at 25 with ellipsis, but last visible col may be cut at screen edge without ellipsis? Let's see: At width 80, last col int_col width 10, fits exactly? At width 100, last col? Need to handle partial last col: show truncated without ellipsis? Ratatui Paragraph will truncate automatically.
            visible_cols.push(ci);
            used += w;
            if used >= avail { break; }
        } else {
            break;
        }
    }
    // If no cols (headers empty?), return
    // Render header row
    if area.height >= 1 {
        let y = area.y;
        // 9 spaces (empty for row numbers)
        // Then headers
        let mut x = area.x + 9;
        for &ci in &visible_cols {
            let h = &app.headers[ci];
            let w = app.col_widths[ci] as u16;
            // Truncate header if needed? Headers capped at 25 already via col_widths, but need to truncate display to 25? Headers in our data are short, but for safety truncate to 25?
            let disp = if h.len() > 25 {
                let chars: Vec<char> = h.chars().collect();
                chars[..24].iter().collect::<String>() + "…"
            } else { h.clone() };
            // Render with padding to w (left-aligned)
            let text = format!("{:<width$}", disp, width = w as usize);
            // But need to handle that last col may be cut at screen edge: ratatui will clip automatically if we render beyond area.width? We should limit width to remaining.
            let remaining = (area.x + area.width).saturating_sub(x);
            let render_w = std::cmp::min(w, remaining);
            if render_w == 0 { break; }
            // Truncate text to render_w (handle unicode? for now bytes, but headers ASCII)
            let trunc: String = text.chars().take(render_w as usize).collect();
            let span = Span::styled(trunc, header_style);
            f.render_widget(Paragraph::new(Line::from(span)), Rect { x, y, width: render_w, height: 1 });
            x += w;
            if x >= area.x + area.width { break; }
        }
    }
    // Separator row
    if area.height >= 2 {
        let y = area.y + 1;
        // Build separator string: ──────┬────... total area.width chars
        // Row number part: ────── (6) + ┬ (1) + ─... for data (area.width-7)
        let total_w = area.width as usize;
        let mut sep = String::new();
        sep.push_str("──────┬");
        if total_w > 7 {
            sep.push_str(&"─".repeat(total_w - 7));
        }
        // Truncate to total_w (handle unicode width? ─ is 1 wide)
        let span = Span::styled(sep, grey);
        f.render_widget(Paragraph::new(Line::from(span)), Rect { x: area.x, y, width: area.width, height: 1 });
    }
    // Data rows
    let vis_h = app.visible_height(area.height);
    for ri in 0..vis_h {
        let y = area.y + 2 + ri as u16;
        if y >= area.y + area.height { break; }
        let data_idx = app.row_offset + ri;
        if data_idx >= app.rows.len() {
            // Empty row: 6 spaces + │ (grey) + rest empty?
            // From capture: `      │` (6 spaces + │)
            let empty_num = Span::raw("      ");
            f.render_widget(Paragraph::new(Line::from(empty_num)), Rect { x: area.x, y, width: 6, height: 1 });
            let sep_span = Span::styled("│", grey);
            f.render_widget(Paragraph::new(Line::from(sep_span)), Rect { x: area.x + 6, y, width: 1, height: 1 });
            // rest empty (no highlight)
            continue;
        }
        let is_selected = data_idx == app.selected_row;
        // Row number: left-aligned in 6 width? e.g., "1     ", "10    "
        let num_str = format!("{:<6}", data_idx + 1);
        let num_style = if is_selected { sel_row_num_style } else { grey };
        // For selected, need bold+underline+grey. Our style matches.
        // But need to handle that unselected row numbers are grey, selected also grey+bold+underline.
        f.render_widget(Paragraph::new(Line::from(Span::styled(num_str, num_style))), Rect { x: area.x, y, width: 6, height: 1 });
        // Separator │
        f.render_widget(Paragraph::new(Line::from(Span::styled("│", grey))), Rect { x: area.x + 6, y, width: 1, height: 1 });
        // 2 spaces padding? Actually data starts at x+9, so x+7 and x+8 are spaces.
        // Then cells
        let mut x = area.x + 9;
        for &ci in &visible_cols {
            let w = app.col_widths[ci] as u16;
            let raw = &app.rows[data_idx][ci];
            let disp = App::truncate_cell(raw);
            let text = format!("{:<width$}", disp, width = w as usize);
            let remaining = (area.x + area.width).saturating_sub(x);
            let render_w = std::cmp::min(w, remaining);
            if render_w == 0 { break; }
            let trunc: String = text.chars().take(render_w as usize).collect();
            let style = if is_selected { sel_cell_style } else { Style::default() };
            f.render_widget(Paragraph::new(Line::from(Span::styled(trunc, style))), Rect { x, y, width: render_w, height: 1 });
            x += w;
            if x >= area.x + area.width { break; }
        }
        // For selected row, need to highlight trailing? Our per-cell highlight covers visible cols, but what about gap to screen edge? Original highlight covers only visible cols (as we saw), not to edge. Good.
    }
}

fn draw_metadata(f: &mut Frame, area: Rect, _app: &App) {
    f.render_widget(Paragraph::new("metadata TODO"), area);
}
fn draw_schema(f: &mut Frame, area: Rect, _app: &App) {
    f.render_widget(Paragraph::new("schema TODO"), area);
}
fn draw_rowgroups(f: &mut Frame, area: Rect, _app: &App) {
    f.render_widget(Paragraph::new("rowgroups TODO"), area);
}
