cat <<'RS' > src/main.rs
use clap::{Arg, Command};
use ratatui::{
    layout::{Alignment, Constraint, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, BorderType, Paragraph},
    Frame,
};
use crossterm::event::{self, Event, KeyCode};

fn cli() -> Command {
    Command::new("parqeye")
        .version("0.0.2")
        .about("Command line tool to visualize parquet files")
        .arg(Arg::new("PATH").help("Path to the parquet file").required(true))
}

struct App {
    path: String,
    tab: usize, // 0 Visualize, 1 Metadata, 2 Schema, 3 RowGroups
    // Visualize state
    headers: Vec<String>,
    rows: Vec<Vec<String>>,
    col_widths: Vec<usize>, // includes +2 padding, min 10 max 27
    selected_row: usize,
    row_offset: usize,
    col_offset: usize, // index of first visible col
}

impl App {
    fn new(path: String) -> Self {
        // Fake data for alltypes_plain for dev
        let headers = vec!["id","bool_col","tinyint_col","smallint_col","int_col","bigint_col","float_col","double_col","date_string_col","string_col","timestamp_col"].into_iter().map(|s| s.to_string()).collect::<Vec<_>>();
        let rows = vec![
            vec!["4","true","0","0","0","0","0.0","0.0","b\"03/01/09\"","b\"0\"","2009-03-01 00:00:00"],
            vec!["5","false","1","1","1","10","1.1","10.1","b\"03/01/09\"","b\"1\"","2009-03-01 00:01:00"],
            vec!["6","true","0","0","0","0","0.0","0.0","b\"04/01/09\"","b\"0\"","2009-04-01 00:00:00"],
            vec!["7","false","1","1","1","10","1.1","10.1","b\"04/01/09\"","b\"1\"","2009-04-01 00:01:00"],
            vec!["2","true","0","0","0","0","0.0","0.0","b\"02/01/09\"","b\"0\"","2009-02-01 00:00:00"],
            vec!["3","false","1","1","1","10","1.1","10.1","b\"02/01/09\"","b\"1\"","2009-02-01 00:01:00"],
            vec!["0","true","0","0","0","0","0.0","0.0","b\"01/01/09\"","b\"0\"","2009-01-01 00:00:00"],
            vec!["1","false","1","1","1","10","1.1","10.1","b\"01/01/09\"","b\"1\"","2009-01-01 00:01:00"],
        ].into_iter().map(|r| r.into_iter().map(|s| s.to_string()).collect()).collect::<Vec<Vec<String>>>();
        let mut col_widths = Vec::new();
        for (ci, h) in headers.iter().enumerate() {
            let mut max_len = h.len();
            for row in &rows {
                let l = row[ci].len();
                if l > max_len { max_len = l; }
            }
            let capped = std::cmp::min(max_len, 25);
            let w = capped + 2;
            let w = std::cmp::max(w, 10);
            col_widths.push(w);
        }
        Self { path, tab: 0, headers, rows, col_widths, selected_row: 0, row_offset: 0, col_offset: 0 }
    }

    fn visible_height(&self, body_height: u16) -> usize {
        // body includes header row (1) + separator (1) + data rows
        if body_height <= 2 { 0 } else { (body_height - 2) as usize }
    }

    fn truncate_cell(s: &str) -> String {
        if s.len() <= 25 {
            s.to_string()
        } else {
            // truncate to 24 chars + ellipsis (handle unicode? for now bytes, but need char boundary)
            // Count chars
            let chars: Vec<char> = s.chars().collect();
            if chars.len() <= 25 {
                s.to_string()
            } else {
                chars[..24].iter().collect::<String>() + "…"
            }
        }
    }
}

fn main() -> std::io::Result<()> {
    let matches = cli().get_matches();
    let path = matches.get_one::<String>("PATH").unwrap().clone();
    let mut terminal = ratatui::init();
    let mut app = App::new(path);
    loop {
        terminal.draw(|f| draw(f, &mut app)).map_err(|e| std::io::Error::other(e.to_string()))?;
        match event::read().map_err(|e| std::io::Error::other(e.to_string()))? {
            Event::Key(key) => {
                match key.code {
                    KeyCode::Char(c) => {
                        let lc = c.to_ascii_lowercase();
                        if lc == 'q' {
                            break;
                        } else if lc == 'u' {
                            // page up
                            handle_page_up(&mut app, terminal.get_frame().area());
                        } else if lc == 'd' {
                            handle_page_down(&mut app, terminal.get_frame().area());
                        }
                    }
                    KeyCode::Tab => {
                        app.tab = (app.tab + 1) % 4;
                    }
                    KeyCode::BackTab => {
                        app.tab = (app.tab + 3) % 4;
                    }
                    KeyCode::Up => {
                        if app.tab == 0 {
                            if app.selected_row > 0 {
                                app.selected_row -= 1;
                                if app.selected_row < app.row_offset {
                                    app.row_offset = app.selected_row;
                                }
                            }
                        }
                    }
                    KeyCode::Down => {
                        if app.tab == 0 {
                            if !app.rows.is_empty() && app.selected_row + 1 < app.rows.len() {
                                app.selected_row += 1;
                                // need visible height to decide scroll; get from terminal size?
                                // For now, use last known? We'll compute from terminal area
                                let area = terminal.get_frame().area();
                                let body_h = area.height.saturating_sub(4); // header 3 + footer 1
                                let vis = if body_h <= 2 { 0 } else { (body_h - 2) as usize };
                                if vis > 0 && app.selected_row >= app.row_offset + vis - 1 {
                                    // scroll to keep second-last? original: offset = sel - vis + 2
                                    app.row_offset = app.selected_row.saturating_sub(vis.saturating_sub(2));
                                }
                            }
                        }
                    }
                    KeyCode::Left => {
                        if app.tab == 0 {
                            if app.col_offset > 0 {
                                app.col_offset -= 1;
                            }
                        }
                    }
                    KeyCode::Right => {
                        if app.tab == 0 {
                            // need to check if can scroll right (more cols hidden)
                            // For now, allow up to headers.len()-1
                            if app.col_offset + 1 < app.headers.len() {
                                app.col_offset += 1;
                            }
                        }
                    }
                    _ => {}
                }
            }
            Event::Resize(_, _) => {}
            _ => {}
        }
    }
    ratatui::restore();
    Ok(())
}

fn handle_page_up(app: &mut App, area: Rect) {
    if app.tab != 0 || app.rows.is_empty() { return; }
    let body_h = area.height.saturating_sub(4);
    let vis = if body_h <= 2 { 0 } else { (body_h - 2) as usize };
    if vis == 0 { return; }
    let page = vis.saturating_sub(1);
    if page == 0 { return; }
    app.selected_row = app.selected_row.saturating_sub(page);
    if app.selected_row < app.row_offset {
        app.row_offset = app.selected_row;
    }
}

fn handle_page_down(app: &mut App, area: Rect) {
    if app.tab != 0 || app.rows.is_empty() { return; }
    let body_h = area.height.saturating_sub(4);
    let vis = if body_h <= 2 { 0 } else { (body_h - 2) as usize };
    if vis == 0 { return; }
    let page = vis.saturating_sub(1);
    if page == 0 { return; }
    let max_idx = app.rows.len() - 1;
    app.selected_row = std::cmp::min(app.selected_row + page, max_idx);
    if app.selected_row >= app.row_offset + vis.saturating_sub(1) {
        // second-last logic: offset = sel - vis + 2
        if vis >= 2 {
            app.row_offset = app.selected_row.saturating_sub(vis - 2);
        } else {
            app.row_offset = app.selected_row;
        }
        // clamp offset to max
        let max_offset = app.rows.len().saturating_sub(vis);
        if app.row_offset > max_offset {
            app.row_offset = max_offset;
        }
    }
}

fn draw(f: &mut Frame, app: &mut App) {
    let area = f.area();
    let chunks = Layout::vertical([Constraint::Length(3), Constraint::Min(0), Constraint::Length(1)]).split(area);
    draw_header(f, chunks[0], app);
    match app.tab {
        0 => draw_visualize(f, chunks[1], app),
        1 => draw_metadata(f, chunks[1], app),
        2 => draw_schema(f, chunks[1], app),
        3 => draw_rowgroups(f, chunks[1], app),
        _ => {}
    }
    draw_footer(f, chunks[2], app);
}

fn draw_header(f: &mut Frame, area: Rect, app: &App) {
    let block = Block::default().borders(Borders::ALL).border_type(BorderType::Rounded).border_style(Style::default().fg(Color::Indexed(11)));
    let inner = block.inner(area);
    f.render_widget(block, area);
    // Tabs
    let tabs = ["Visualize", "Metadata", "Schema", "Row Groups"];
    let mut spans = Vec::new();
    for (i, t) in tabs.iter().enumerate() {
        if i > 0 { spans.push(Span::raw("   ")); }
        if i == app.tab {
            spans.push(Span::styled(*t, Style::default().add_modifier(Modifier::REVERSED)));
        } else {
            spans.push(Span::raw(*t));
        }
    }
    let tabs_line = Line::from(spans);
    // Render tabs at inner.x+1, inner.y (1 space padding)
    // Need to handle width: tabs take left, filename right
    // Compute tabs width: sum len + separators
    let tabs_width: usize = tabs.iter().map(|s| s.len()).sum::<usize>() + 3*3; // 3 separators *3 spaces
    let tabs_area = Rect { x: inner.x + 1, y: inner.y, width: tabs_width as u16, height: 1 };
    f.render_widget(Paragraph::new(tabs_line), tabs_area);
    // Filename right-aligned with 1 space padding from border
    let fname = app.path.clone();
    let fw = fname.len() as u16;
    // inner.width includes full inner (excluding borders). Right pad 1.
    if (fw + 1) <= inner.width {
        let fx = inner.x + inner.width - 1 - fw;
        let farea = Rect { x: fx, y: inner.y, width: fw, height: 1 };
        let span = Span::styled(fname, Style::default().fg(Color::Indexed(2)));
        f.render_widget(Paragraph::new(Line::from(span)), farea);
    }
}

fn draw_footer(f: &mut Frame, area: Rect, app: &App) {
    // Left: parqeye bold green
    // Right: hints per tab, right-aligned
    let left = Span::styled("parqeye", Style::default().fg(Color::Indexed(2)).add_modifier(Modifier::BOLD));
    // Build right hints
    let right_line: Line = match app.tab {
        0 => Line::from(vec![
            Span::styled("↑", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("↓", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Row"),
            Span::styled(" | ", Style::default().fg(Color::Indexed(15))),
            Span::styled("→", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("←", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Column"),
            Span::styled(" | ", Style::default().fg(Color::Indexed(15))),
            Span::styled("u", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("d", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Page - "),
            Span::styled("[Tab]", Style::default().fg(Color::Indexed(2))),
            Span::raw(" Next Tab, "),
            Span::styled("[Q]", Style::default().fg(Color::Indexed(4))),
            Span::raw("uit"),
        ]),
        1 => Line::from(vec![
            Span::styled("[Tab]", Style::default().fg(Color::Indexed(2))),
            Span::raw(" Next Tab, "),
            Span::styled("[Q]", Style::default().fg(Color::Indexed(4))),
            Span::raw("uit"),
        ]),
        2 => Line::from(vec![
            Span::styled("←", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("→", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Scroll, "),
            Span::styled("↑", Style::default().fg(Color::Indexed(2))),
            Span::styled("/", Style::default().fg(Color::Indexed(15))),
            Span::styled("↓", Style::default().fg(Color::Indexed(4))),
            Span::raw(" : Schema - "),
            Span::styled("[Tab]", Style::default().fg(Color::Indexed(2))),
            Span::raw(" Next Tab, "),
            Span::styled("[Q]", Style::default().fg(Color::Indexed(4))),
            Span::raw("uit"),
        ]),
        3 => Line::from(vec![
            Span::styled("→", Style::default().fg(Color::Indexed(2))),
