            Span::raw(" : Schema - "),
            Span::styled("[Tab]", Style::default().fg(Color::Indexed(2))),
            Span::raw(" Next Tab, "),
            Span::styled("[Q]", Style::default().fg(Color::Indexed(4))),
            Span::raw("uit"),
        ]),
        _ => Line::from(""),
    };
    // Render left at x, right right-aligned
    f.render_widget(Paragraph::new(Line::from(left)), Rect { x: area.x, y: area.y, width: 7, height: 1 });
    let rw = right_line.width() as u16;
    if rw <= area.width.saturating_sub(8) {
        let rx = area.x + area.width - rw;
        f.render_widget(Paragraph::new(right_line), Rect { x: rx, y: area.y, width: rw, height: 1 });
