        let rx = area.x + 8;
        let w = area.width.saturating_sub(8);
        f.render_widget(Paragraph::new(right_line), Rect { x: rx, y: area.y, width: w, height: 1 });
    }
}

fn draw_visualize(f: &mut Frame, area: Rect, app: &App) {
    if area.height == 0 || area.width == 0 { return; }
    // area is body (without header/footer)
    // Need to render: col headers row (y=0), separator (y=1), data rows (y=2..)
    // Row number area width 6, separator │ at x=6, data starts at x=9 (6+1+2)
    // Header line: 9 spaces + headers
    // Separator: ──────┬────... in grey
    // Data: row_num (grey or bold+underline+grey) + │ + cells
    let header_style = Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD);
    let grey = Style::default().fg(Color::Indexed(8));
    let sel_row_num_style = Style::default().fg(Color::Indexed(8)).add_modifier(Modifier::BOLD | Modifier::UNDERLINED);
    let sel_cell_style = Style::default().fg(Color::Indexed(15)).bg(Color::Rgb(60,60,60)).add_modifier(Modifier::BOLD);

    // Determine visible cols based on col_offset and area.width
    // Data starts at x=9 (0-indexed within area? area.x is 0, data at area.x+9)
    // Available width for data = area.width.saturating_sub(9)
    let avail = area.width.saturating_sub(9) as usize;
    let mut visible_cols: Vec<usize> = Vec::new();
    let mut used = 0usize;
    for ci in app.col_offset..app.headers.len() {
        let w = app.col_widths[ci];
        if used + w <= avail || visible_cols.is_empty() {
            // Always show at least one col even if wider than avail? Original shows truncated last col at edge (cut, not ellipsis? For Visualize, last col truncated at screen edge without ellipsis? Actually for Visualize, cells truncated at 25 with ellipsis, but last visible col may be cut at screen edge without ellipsis? Let's see: At width 80, last col int_col width 10, fits exactly? At width 100, last col? Need to handle partial last col: show truncated without ellipsis? Ratatui Paragraph will truncate automatically.
            visible_cols.push(ci);
            used += w;
            if used >= avail { break; }
        } else {
            break;
        }
    }
    // If no cols (headers empty?), return
    // Render header row
    if area.height >= 1 {
        let y = area.y;
        // 9 spaces (empty for row numbers)
        // Then headers
        let mut x = area.x + 9;
        for &ci in &visible_cols {
            let h = &app.headers[ci];
            let w = app.col_widths[ci] as u16;
            // Truncate header if needed? Headers capped at 25 already via col_widths, but need to truncate display to 25? Headers in our data are short, but for safety truncate to 25?
            let disp = if h.len() > 25 {
                let chars: Vec<char> = h.chars().collect();
                chars[..24].iter().collect::<String>() + "…"
            } else { h.clone() };
            // Render with padding to w (left-aligned)
            let text = format!("{:<width$}", disp, width = w as usize);
            // But need to handle that last col may be cut at screen edge: ratatui will clip automatically if we render beyond area.width? We should limit width to remaining.
            let remaining = (area.x + area.width).saturating_sub(x);
            let render_w = std::cmp::min(w, remaining);
            if render_w == 0 { break; }
            // Truncate text to render_w (handle unicode? for now bytes, but headers ASCII)
            let trunc: String = text.chars().take(render_w as usize).collect();
            let span = Span::styled(trunc, header_style);
            f.render_widget(Paragraph::new(Line::from(span)), Rect { x, y, width: render_w, height: 1 });
            x += w;
            if x >= area.x + area.width { break; }
        }
    }
    // Separator row
    if area.height >= 2 {
        let y = area.y + 1;
        // Build separator string: ──────┬────... total area.width chars
        // Row number part: ────── (6) + ┬ (1) + ─... for data (area.width-7)
        let total_w = area.width as usize;
        let mut sep = String::new();
        sep.push_str("──────┬");
        if total_w > 7 {
            sep.push_str(&"─".repeat(total_w - 7));
        }
        // Truncate to total_w (handle unicode width? ─ is 1 wide)
        let span = Span::styled(sep, grey);
        f.render_widget(Paragraph::new(Line::from(span)), Rect { x: area.x, y, width: area.width, height: 1 });
    }
    // Data rows
    let vis_h = app.visible_height(area.height);
    for ri in 0..vis_h {
        let y = area.y + 2 + ri as u16;
        if y >= area.y + area.height { break; }
        let data_idx = app.row_offset + ri;
        if data_idx >= app.rows.len() {
            // Empty row: 6 spaces + │ (grey) + rest empty?
            // From capture: `      │` (6 spaces + │)
            let empty_num = Span::raw("      ");
            f.render_widget(Paragraph::new(Line::from(empty_num)), Rect { x: area.x, y, width: 6, height: 1 });
            let sep_span = Span::styled("│", grey);
            f.render_widget(Paragraph::new(Line::from(sep_span)), Rect { x: area.x + 6, y, width: 1, height: 1 });
            // rest empty (no highlight)
            continue;
        }
        let is_selected = data_idx == app.selected_row;
        // Row number: left-aligned in 6 width? e.g., "1     ", "10    "
        let num_str = format!("{:<6}", data_idx + 1);
        let num_style = if is_selected { sel_row_num_style } else { grey };
        // For selected, need bold+underline+grey. Our style matches.
        // But need to handle that unselected row numbers are grey, selected also grey+bold+underline.
        f.render_widget(Paragraph::new(Line::from(Span::styled(num_str, num_style))), Rect { x: area.x, y, width: 6, height: 1 });
        // Separator │
        f.render_widget(Paragraph::new(Line::from(Span::styled("│", grey))), Rect { x: area.x + 6, y, width: 1, height: 1 });
        // 2 spaces padding? Actually data starts at x+9, so x+7 and x+8 are spaces.
        // Then cells
        let mut x = area.x + 9;
        for &ci in &visible_cols {
            let w = app.col_widths[ci] as u16;
            let raw = &app.rows[data_idx][ci];
            let disp = App::truncate_cell(raw);
            let text = format!("{:<width$}", disp, width = w as usize);
            let remaining = (area.x + area.width).saturating_sub(x);
            let render_w = std::cmp::min(w, remaining);
            if render_w == 0 { break; }
            let trunc: String = text.chars().take(render_w as usize).collect();
            let style = if is_selected { sel_cell_style } else { Style::default() };
            f.render_widget(Paragraph::new(Line::from(Span::styled(trunc, style))), Rect { x, y, width: render_w, height: 1 });
            x += w;
            if x >= area.x + area.width { break; }
        }
        // For selected row, need to highlight trailing? Our per-cell highlight covers visible cols, but what about gap to screen edge? Original highlight covers only visible cols (as we saw), not to edge. Good.
    }
}

